404	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
405	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
406	  const list = flags.get(name);
407	  if (!list || list.length !== 1) return null;
408	  return list[0];
409	}
