411	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
412	function dateFlag(value: string, label: string): { date: string } | string {
413	  const v = value.trim();
414	  if (parseUtcDate(v) === null) {
415	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
416	  }
417	  return { date: v };
418	}
