420	function cmdRule(rest: string[]): number {
421	  const [sub, ...subrest] = rest;
422	  if (sub === 'list') {
423	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
424	    return cmdRuleList();
425	  }
426	  if (sub === 'create') {
427	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz', '--max-interval', '--schedule']);
428	    if (typeof flags === 'string') return usageError(flags);
429	    const idRaw = oneFlag(flags, '--id');
430	    const deviceList = flags.get('--device');
431	    const groupList = flags.get('--group');
432	    const thresholdRaw = oneFlag(flags, '--threshold');
433	    const tzList = flags.get('--tz');
434	    const maxIntervalList = flags.get('--max-interval');
435	    const scheduleList = flags.get('--schedule');
436	    if (idRaw === null || thresholdRaw === null) {
437	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
438	    }
439	    if (tzList !== undefined && tzList.length !== 1) {
440	      return usageError("'rule create' 的 --tz 只能出现一次");
441	    }
442	    if (maxIntervalList !== undefined && maxIntervalList.length !== 1) {
443	      return usageError("'rule create' 的 --max-interval 只能出现一次");
444	    }
445	    if (scheduleList !== undefined && scheduleList.length !== 1) {
446	      return usageError("'rule create' 的 --schedule 只能出现一次");
447	    }
448	    const hasDevice = deviceList !== undefined;
449	    const hasGroup = groupList !== undefined;
450	    if (hasDevice === hasGroup) {
451	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
452	    }
453	    if ((deviceList !== undefined && deviceList.length !== 1) ||
454	      (groupList !== undefined && groupList.length !== 1)) {
455	      return usageError("'rule create' 的目标选项只能出现一次");
456	    }
457	    const id = idRaw.trim();
458	    if (id === '') return usageError('规则标识不能为空');
459	    const thresholdMilli = parseKwh(thresholdRaw.trim());
460	    if (thresholdMilli === null) {
461	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
462	    }
463	    // 时区省略与显式 UTC 等价;按运行环境解析后的规范名存储与比较。
464	    let tz = 'UTC';
465	    if (tzList !== undefined) {
466	      const tzRaw = tzList[0].trim();
467	      if (tzRaw === '') return usageError("'--tz' 的值不能为空");
468	      const canonical = canonicalTimezone(tzRaw);
469	      if (canonical === null) {
470	        return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
471	      }
472	      tz = canonical;
473	    }
474	    // 采样间隔限制省略为无上限,创建后固定。
475	    let maxInterval: number | undefined;
476	    if (maxIntervalList !== undefined) {
477	      const parsed = parseMaxInterval(maxIntervalList[0]);
478	      if (parsed === null) {
479	        return usageError(`选项 '--max-interval' 的值无效: '${maxIntervalList[0].trim()}'(需正整数秒数)`);
480	      }
481	      maxInterval = parsed;
482	    }
483	    // 运行时间表(每周窗口 + 日期例外):仅分组规则可指定(非运行模式),省略为
484	    // 全天模式。创建时保存解析后的每周窗口并集与例外日期映射规范形,原文件后续
485	    // 修改、移动或删除不影响规则。
486	    let schedule: Schedule | undefined;
487	    if (scheduleList !== undefined) {
488	      if (hasDevice) {
489	        return usageError("'rule create' 的 --schedule 只适用于分组规则(设备规则不接受时间表)");
490	      }
491	      const scheduleRaw = scheduleList[0];
492	      if (scheduleRaw.trim() === '') return usageError("'--schedule' 的值不能为空");
493	      let text: string;
494	      try {
495	        text = readFileSync(scheduleRaw, 'utf8');
496	      } catch (e) {
497	        console.error(`meterwatch: cannot read schedule file ${scheduleRaw}: ${(e as Error).message}`);
498	        return 1;
499	      }
500	      const parsed = parseSchedule(text);
501	      if (typeof parsed === 'string') {
502	        console.error(`meterwatch: invalid schedule file ${scheduleRaw}: ${parsed}`);
503	        return 2;
504	      }
505	      schedule = {
506	        windows: canonicalizeWindows(parsed.windows),
507	        exceptions: canonicalizeExceptions(parsed.exceptions),
508	      };
509	    }
510	    if (hasDevice) {
511	      const device = (deviceList as string[])[0].trim();
512	      if (device === '') return usageError("'--device' 的值不能为空");
513	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli, tz, maxInterval });
514	    }
515	    const group = (groupList as string[])[0].trim();
516	    if (group === '') return usageError("'--group' 的值不能为空");
517	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli, tz, maxInterval, schedule });
518	  }
519	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
520	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
521	}
