523	function cmdEvaluateEntry(rest: string[]): number {
524	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
525	  if (typeof flags === 'string') return usageError(flags);
526	  const ruleRaw = oneFlag(flags, '--rule');
527	  const fromRaw = oneFlag(flags, '--from');
528	  const toRaw = oneFlag(flags, '--to');
529	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
530	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
531	  }
532	  const ruleId = ruleRaw.trim();
533	  if (ruleId === '') return usageError('规则标识不能为空');
534	  const from = dateFlag(fromRaw, '起始日期');
535	  if (typeof from === 'string') return usageError(from);
536	  const to = dateFlag(toRaw, '结束日期');
537	  if (typeof to === 'string') return usageError(to);
538	  if (from.date >= to.date) return usageError('评估起日必须早于止日(--from < --to)');
539	  return cmdEvaluate({ ruleId, from: from.date, to: to.date });
540	}
