```ts
interface RescueJournal {
  phase: RescuePhase;
  preservedDir: string;
  stores: string[];
  preserved: Array<{ name: string; hadOld: boolean }>;
}

function parseRescueJournal(data: unknown): RescueJournal | null {
  const o = data as Record<string, unknown>;
  if (o === null || typeof o !== 'object' ||
      o.format !== RESCUE_JOURNAL_FORMAT || o.version !== 1 ||
      typeof o.preservedDir !== 'string' || o.preservedDir.length === 0 ||
      basename(o.preservedDir) !== o.preservedDir ||
      !Array.isArray(o.stores) || o.stores.length === 0 ||
      !Array.isArray(o.preserved)) return null;
  let phase: RescuePhase = 'committing';
  if (o.phase !== undefined) {
    if (typeof o.phase !== 'string' || !RESCUE_PHASES.includes(o.phase)) return null;
    phase = o.phase;
  }
  const stores: string[] = [];
  for (const s of o.stores) {
    if (typeof s !== 'string' || s.length === 0 || basename(s) !== s) return null;
    stores.push(s);
  }
  const seen = new Set<string>();
  const preserved = [];
  for (const f of o.preserved) {
    if (f === null || typeof f !== 'object' || typeof f.name !== 'string' ||
        f.name.length === 0 || basename(f.name) !== f.name ||
        typeof f.hadOld !== 'boolean' || seen.has(f.name)) return null;
    seen.add(f.name);
    preserved.push({ name: f.name, hadOld: f.hadOld });
  }
  return { phase, preservedDir: o.preservedDir, stores, preserved };
}
```

