function rescueRollbackPass(dir: string, journal: RescueJournal): void {
  const preservedDir = join(dir, journal.preservedDir);
  for (const entry of journal.preserved) {
    const live = join(dir, entry.name);
    const kept = join(preservedDir, entry.name);
    if (entry.hadOld) {
      if (!isRegularFile(kept)) {
        throw new StoreError(`cannot restore pre-rescue ${live}: preserved copy ${kept} is missing or not a regular file`);
      }
      if (existsSync(live)) {
        if (!isRegularFile(live)) throw new StoreError(`cannot restore pre-rescue ${live}: live path exists but is not a regular file`);
        rmSync(live);
      }
      copyFileSync(kept, live);
    } else {
      if (existsSync(kept)) {
        throw new StoreError(`cannot restore pre-rescue ${live}: preserved copy ${kept} exists but the journal records it was absent`);
      }
      if (existsSync(live)) {
        if (!isRegularFile(live)) throw new StoreError(`cannot restore missing state for ${live}: live path is not a regular file`);
        rmSync(live);
      }
    }
  }
}
