function performRescue(dir: string, files: Array<{ path: string; body: string }>): string {
  // returns preservedDir name (for reporting)
  const journalPath = join(dir, RESCUE_JOURNAL_NAME);
  const storeNames = files.map((f) => basename(f.path));
  // 1. 新内容写入临时文件(尚未有任何替换;中断后由启动清理)。
  for (const f of files) writeFileSync(f.path + RESCUE_NEW_SUFFIX, f.body, 'utf8');
  // 2. 固定名字集的留存记录(不依据坏日志里的文件名)。
  const preserved = preservedNames().map((name) => ({ name, hadOld: existsSync(join(dir, name)) }));
  // 3. 选择不覆盖已有留存的目录名(重复救援不丢材料、不改写历史)。
  let seq = 1;
  let preservedDir = `${PRESERVED_PREFIX}${seq}`;
  while (existsSync(join(dir, preservedDir))) { seq++; preservedDir = `${PRESERVED_PREFIX}${seq}`; }
  const journal: RescueJournal = { phase: 'preserving', preservedDir, stores: storeNames, preserved };
  // 4. 救援日志(先记 preserving:此阶段中断等同未开始,启动时退回救援前状态)。
  writeRescueJournalPhase(dir, journal, 'preserving');
  // 5. 持久留存:原始字节 + 缺失状态;留存不完整不得替换。
  try {
    mkdirSync(join(dir, preservedDir));
    for (const entry of preserved) {
      if (entry.hadOld) copyFileSync(join(dir, entry.name), join(dir, preservedDir, entry.name));
    }
    writeFileSync(join(dir, preservedDir, 'rescue-manifest.json'),
      JSON.stringify({ format: 'meterwatch-rescue-manifest', version: 1, preserved }, null, 2) + '\n', 'utf8');
  } catch (e) {
    // 留存失败:不替换;尽力退回救援前状态(业务文件与旧事务材料尚未被改动)。
    try { rmSync(journalPath); } catch {}
    for (const f of files) { try { rmSync(f.path + RESCUE_NEW_SUFFIX); } catch {} }
    try { rmSync(join(dir, preservedDir), { recursive: true, force: true }); } catch {}
    throw new StoreError(`cannot preserve pre-rescue state in ${dir}: ${(e as Error).message}; nothing was replaced`);
  }
  // 6. 进入替换。
  writeRescueJournalPhase(dir, journal, 'committing');
  try {
    rescueRollForwardPass(dir, journal);
  } catch (e) {
    // 受控失败:确定回退后不得改向。
    try {
      writeRescueJournalPhase(dir, journal, 'rolling-back');
    } catch (we) {
      throw new StoreError(`rescue failed (${(e as Error).message}) and the rollback could not be started (${(we as Error).message}); data directory ${dir} keeps its rescue materials - run any meterwatch command again to continue the rollback`);
    }
    try {
      rescueRollbackPass(dir, journal);
      rescueRollbackCleanup(dir, journal);
    } catch (re) {
      throw new StoreError(`rescue failed (${(e as Error).message}); rollback is in progress and could not finish (${(re as Error).message}); data directory ${dir} keeps all materials needed to restore the pre-rescue state - run any meterwatch command again to finish it`);
    }
    throw new StoreError(`rescue failed: ${(e as Error).message}; pre-rescue state restored`);
  }
  // 7. 完成收尾。
  try {
    writeRescueJournalPhase(dir, journal, 'done');
    rescueCommitCleanup(dir, journal);
  } catch (e) {
    throw new StoreError(`snapshot state was committed but post-rescue cleanup failed: ${(e as Error).message}; run any meterwatch command again to finish cleanup`);
  }
  return preservedDir;
}
