    preservedDir = performRescue(dir, storeBodies(loaded));
  } catch (e) {
    if (e instanceof StoreError) { err(e.message); return 1; }
    throw e;
  }
  console.log(`rescued from snapshot '${snapshotPath}': ${countsReport(...)}`);
  console.log(`pre-rescue state preserved in '${join(dir, preservedDir)}' (kept; not cleaned automatically)`);
  return 0;
}
