```ts
export function withRescueCoordination<T>(action: () => T): T | number {
  const dir = dataDirPath();
  try { mkdirSync(dir, { recursive: true }); } catch (e) { err(...); return 1; }
  const lockError = acquireLock(dir);
  if (lockError !== null) { err(lockError); return 1; }
  try {
    const rescueError = continueInterruptedRescue(dir);
    if (rescueError !== null) { err(rescueError); return 1; }
    return action();
  } finally { releaseLock(dir); }
}
