}

/**
 * 救援回滚:按留存记录还原救援前三个业务文件与旧事务材料的内容与存在状态,
 * 逐条幂等,可在任意一步中断后续接。留存字节缺失或与记录矛盾时抛错并保留
 * 全部材料,不猜测。
 */
function rescueRollbackPass(dir: string, journal: RescueJournal): void {
